// Extract & Qualify Subscriber Data from ManyChat Payload
const rawBody = $('ManyChat Webhook Ingest').item.json.body || {};
const customFields = rawBody.custom_fields || {};

const subscriberId = String(rawBody.subscriber_id || rawBody.id || customFields.subscriber_id || '');
const firstName = rawBody.first_name || customFields.first_name || 'there';
const lastName = rawBody.last_name || '';
const phone = rawBody.phone || customFields.phone || '';
const email = (rawBody.email || customFields.email || '').trim().toLowerCase();
const userMessage = rawBody.user_message || customFields.last_user_input || rawBody.last_input_text || 'Tell me about your services';
const budget = customFields.budget_range || rawBody.budget || '$5k-$15k';
const timeline = customFields.timeline || rawBody.timeline || 'This Month';
const interest = customFields.interest || rawBody.interest || 'AI Automation';

// Lead Scoring Logic
let score = 0;
if (budget.includes('15k+') || budget.includes('20k+')) score += 40;
else if (budget.includes('5k') || budget.includes('10k')) score += 25;
else score += 10;

if (timeline.toLowerCase().includes('week') || timeline.toLowerCase().includes('now')) score += 30;
else if (timeline.toLowerCase().includes('month')) score += 20;
else score += 10;

if (phone) score += 15;
if (email) score += 15;

const leadTier = score >= 70 ? 'HOT_LEAD' : (score >= 40 ? 'WARM_LEAD' : 'NURTURE_LEAD');

return [{
  json: {
    subscriber_id: subscriberId,
    first_name: firstName,
    last_name: lastName,
    phone: phone,
    email: email,
    user_message: userMessage,
    budget: budget,
    timeline: timeline,
    interest: interest,
    lead_score: score,
    lead_tier: leadTier,
    isHotLead: leadTier === 'HOT_LEAD',
    received_at: new Date().toISOString()
  }
}];

