// Prepare ManyChat WhatsApp Push Payload
const subscriber = $('Parse & Qualify Subscriber').item.json;
const aiRes = $('AI WhatsApp Copy Generator').item.json;

const generatedText = aiRes.choices && aiRes.choices[0] && aiRes.choices[0].message
  ? aiRes.choices[0].message.content
  : `Hi ${subscriber.first_name}, thanks for reaching out! Our team has received your inquiry regarding ${subscriber.interest} and will reply shortly.`;

return [{
  json: {
    subscriber_id: subscriber.subscriber_id,
    message_text: generatedText,
    lead_score: subscriber.lead_score,
    lead_tier: subscriber.lead_tier,
    isHotLead: subscriber.isHotLead,
    first_name: subscriber.first_name,
    phone: subscriber.phone
  }
}];

